      render: (ma) => <span className="font-mono text-xs">{ma}</span>,
    },
    { title: "Nhiệm vụ", dataIndex: "ten", ellipsis: true },
    {
      title: "Lớp",
      dataIndex: "lop",
      width: 80,
      render: (lop) => {
        const cfg = LOP_CONFIG[lop as 1|2|3|4];
        return <Tag style={{ color: cfg.color, backgroundColor: cfg.bgColor, borderColor: cfg.borderColor }}>{cfg.icon} {lop}</Tag>;
      },
    },
    {
      title: "Thời hạn",
      dataIndex: "thoiHan",
      width: 110,
      render: (d, rec) => {
        const overdue = isOverdue(d) && rec.trangThai !== "hoan-thanh";
        return (
          <span className={overdue ? "text-red-500 font-semibold" : "text-orange-500"}>
            {overdue && <WarningOutlined className="mr-1" />}
            {formatDate(d)}
          </span>
        );
      },
    },
    {
      title: "Tiến độ",
      dataIndex: "tienDo",
      width: 100,
      render: (p) => <Progress percent={p} size="small" />,
    },
  ];

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <div className="hero-gradient text-white px-8 py-6">
        <div className="max-w-7xl mx-auto">
          <div className="flex items-center gap-3 mb-1">
            <ApartmentOutlined className="text-2xl" />
            <div>
              <h1 className="text-2xl font-bold">Dashboard Lãnh đạo</h1>
              <p className="text-blue-200 text-sm">
                Giám sát tiến độ triển khai Khung Kiến trúc Số — Tỉnh Vĩnh Long
              </p>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-8 py-6 space-y-6">
        {/* Cảnh báo trễ hạn */}
        {stats.treHan > 0 && (
          <Alert
            message={`⚠️ Có ${stats.treHan} nhiệm vụ trễ hạn cần xử lý gấp`}
            type="error"
            showIcon
            className="rounded-xl"
          />
        )}

        {/* 5 Stat Cards */}
        <div className="grid grid-cols-5 gap-4">
          {[
            {
              title: "Tổng nhiệm vụ",
              value: stats.tongNhiemVu,
              color: "#1677ff",
              icon: <ClockCircleOutlined />,
              bg: "#e6f4ff",
            },
            {
              title: "Hoàn thành",
              value: stats.hoanThanh,
              color: "#52c41a",
              icon: <CheckCircleOutlined />,
              bg: "#f6ffed",
            },
            {
              title: "Đang thực hiện",
              value: stats.dangThucHien,
              color: "#1677ff",
              icon: <ClockCircleOutlined />,
              bg: "#e6f4ff",
            },
            {
              title: "Trễ hạn",
              value: stats.treHan,
              color: "#ff4d4f",
              icon: <WarningOutlined />,
              bg: "#fff2f0",
            },
            {
              title: "Hệ thống số",
              value: stats.tongHeThong,
              color: "#722ed1",
              icon: <DatabaseOutlined />,
              bg: "#f9f0ff",
            },
          ].map((s) => (
            <Card
              key={s.title}
              className="stat-card border-0"
              style={{ backgroundColor: s.bg }}
            >
              <div className="flex items-center gap-3">
                <div
                  className="w-10 h-10 rounded-xl flex items-center justify-center text-lg"
                  style={{ backgroundColor: s.color + "20", color: s.color }}
                >
                  {s.icon}
                </div>
                <div>
                  <Statistic
                    title={<span className="text-gray-500 text-xs">{s.title}</span>}
                    value={s.value}
                    valueStyle={{ color: s.color, fontSize: 28, fontWeight: 700 }}
                  />
                </div>
              </div>
            </Card>
          ))}
        </div>

        {/* Progress tổng thể */}
        <Card className="shadow-sm">
          <div className="flex items-center justify-between mb-3">
            <span className="font-bold text-gray-700 text-lg">Tiến độ tổng thể</span>
            <span className="text-2xl font-bold text-blue-600">{stats.phanTramHoanThanh}%</span>
          </div>
          <Progress
            percent={stats.phanTramHoanThanh}
            strokeWidth={16}
            strokeColor={{
              "0%": "#1677ff",
              "100%": "#52c41a",
            }}
            trailColor="#e8e8e8"
            format={(p) => `${p}% hoàn thành`}
          />
          <div className="flex gap-6 mt-3 text-sm text-gray-500">
            <span>✅ Hoàn thành: {stats.hoanThanh}</span>
            <span>🔵 Đang thực hiện: {stats.dangThucHien}</span>
            <span>⚪ Chưa bắt đầu: {stats.chuaBatDau}</span>
            <span>🔴 Trễ hạn: {stats.treHan}</span>
          </div>
        </Card>

        {/* Charts */}
        <div className="grid grid-cols-2 gap-6">
          {/* Pie chart */}
          <Card title="Phân bổ trạng thái nhiệm vụ" className="shadow-sm">
            <ResponsiveContainer width="100%" height={280}>
              <PieChart>
                <Pie
                  data={pieData}
                  cx="50%"
                  cy="50%"
                  innerRadius={70}
                  outerRadius={110}
                  paddingAngle={3}
                  dataKey="value"
                  label={({ name, percent }) => `${name} (${(percent * 100).toFixed(0)}%)`}
                >
                  {pieData.map((entry, index) => (
                    <Cell key={index} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </Card>

          {/* Bar chart by layer */}
          <Card title="Tiến độ theo lớp kiến trúc" className="shadow-sm">
            <ResponsiveContainer width="100%" height={280}>
              <BarChart data={barData} margin={{ top: 5, right: 30, left: 0, bottom: 5 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                <XAxis dataKey="name" tick={{ fontSize: 11 }} />
                <YAxis tick={{ fontSize: 11 }} />
                <Tooltip />
                <Legend />
                <Bar dataKey="Hoàn thành" fill="#52c41a" radius={[4, 4, 0, 0]} />
                <Bar dataKey="Còn lại" fill="#e8e8e8" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </Card>
        </div>

        {/* 4 Lớp quick view */}
        <div className="grid grid-cols-4 gap-4">
          {stats.nhiemVuTheoLop.map((l) => {
            const cfg = LOP_CONFIG[l.lop as 1|2|3|4];
            const pct = l.total > 0 ? Math.round((l.hoanThanh / l.total) * 100) : 0;
            return (
              <Card
                key={l.lop}
                size="small"
                className="lop-card"
                style={{ borderColor: cfg.borderColor, backgroundColor: cfg.bgColor }}
              >
                <div className="flex items-center gap-2 mb-2">
                  <span className="text-xl">{cfg.icon}</span>
                  <div>
                    <div className="font-bold text-xs" style={{ color: cfg.color }}>
                      Lớp {l.lop}
                    </div>
                    <div className="text-xs text-gray-500">{l.total} nhiệm vụ</div>
                  </div>
                </div>
                <Progress percent={pct} size="small" strokeColor={cfg.color} />
                <div className="text-xs text-gray-400 mt-1">
                  {l.hoanThanh}/{l.total} hoàn thành
                </div>
              </Card>
            );
          })}
        </div>

        {/* Cảnh báo nhiệm vụ sắp hạn/trễ hạn */}
        {stats.nhiemVuSapHanOrTreHan.length > 0 && (
          <Card
            title={
              <span className="flex items-center gap-2 text-orange-600">
                <WarningOutlined /> Nhiệm vụ cần chú ý (sắp đến hạn hoặc trễ hạn)
              </span>
            }
            className="shadow-sm border-orange-200"
            headStyle={{ backgroundColor: "#fff7e6", borderBottom: "1px solid #ffd591" }}
          >
            <Table
              columns={alertColumns}
              dataSource={stats.nhiemVuSapHanOrTreHan}
              rowKey="id"
              pagination={false}
              size="small"
              rowClassName={(r) =>
                isOverdue(r.thoiHan) && r.trangThai !== "hoan-thanh"
                  ? "bg-red-50"
                  : "bg-orange-50"
              }
            />
          </Card>
        )}
      </div>
    </div>
  );
}

"use client";
import { useEffect, useState } from "react";
import { signIn, signOut, useSession } from "next-auth/react";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { Layout, Menu, Button, Avatar, Dropdown, Spin, Tag } from "antd";
import {
  DashboardOutlined,
  ApartmentOutlined,
  AppstoreOutlined,
  OrderedListOutlined,
  UploadOutlined,
  UserOutlined,
  LogoutOutlined,
  HomeOutlined,
} from "@ant-design/icons";
import { SessionProvider } from "next-auth/react";

const { Sider, Header, Content } = Layout;

function AdminLayoutInner({ children }: { children: React.ReactNode }) {
  const { data: session, status } = useSession();
  const pathname = usePathname();
  const router = useRouter();

  useEffect(() => {
    if (status === "unauthenticated") {
      router.push("/login");
    }
  }, [status, router]);

  if (status === "loading") {
    return (
      <div className="flex justify-center items-center min-h-screen">
        <Spin size="large" tip="Đang kiểm tra đăng nhập..." />
      </div>
    );
  }

  if (!session) return null;

  const menuItems = [
    { key: "/admin", icon: <DashboardOutlined />, label: <Link href="/admin">Dashboard</Link> },
    { key: "/admin/khung", icon: <ApartmentOutlined />, label: <Link href="/admin/khung">Thông tin Khung KTS</Link> },
    { key: "/admin/he-thong", icon: <AppstoreOutlined />, label: <Link href="/admin/he-thong">Hệ thống số</Link> },
    { key: "/admin/nhiem-vu", icon: <OrderedListOutlined />, label: <Link href="/admin/nhiem-vu">Nhiệm vụ & Lộ trình</Link> },
    { key: "/admin/import", icon: <UploadOutlined />, label: <Link href="/admin/import">Import XLSX</Link> },
  ];

  const userMenu = {
    items: [
      { key: "portal", icon: <HomeOutlined />, label: <Link href="/">Về trang portal</Link> },
      { key: "logout", icon: <LogoutOutlined />, label: "Đăng xuất", danger: true, onClick: () => signOut({ callbackUrl: "/login" }) },
    ],
  };

  const user = session.user as { name: string; email: string; role: string };

  return (
    <Layout style={{ minHeight: "100vh" }}>
      <Sider width={220} theme="dark" style={{ background: "#001a3e" }}>
        <div className="p-4 border-b border-blue-900">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-blue-500 rounded-lg flex items-center justify-center">
              <ApartmentOutlined className="text-white text-sm" />
            </div>
            <div>
              <div className="text-white text-sm font-bold leading-tight">KTS Vĩnh Long</div>
              <div className="text-blue-300 text-xs">Quản trị hệ thống</div>
            </div>
          </div>
        </div>
        <Menu
          theme="dark"
          mode="inline"
          selectedKeys={[pathname]}
          items={menuItems}
          style={{ background: "#001a3e", border: "none", marginTop: 8 }}
        />
      </Sider>
      <Layout>
        <Header
          style={{
            background: "white",
            padding: "0 24px",
            borderBottom: "1px solid #f0f0f0",
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            boxShadow: "0 1px 4px rgba(0,0,0,0.05)",
          }}
        >
          <div className="text-gray-500 text-sm">
            Hệ thống Quản lý Khung Kiến trúc Số — Tỉnh Vĩnh Long
          </div>
          <Dropdown menu={userMenu} trigger={["click"]}>
            <div className="flex items-center gap-2 cursor-pointer hover:bg-gray-50 px-3 py-1 rounded-lg">
              <Avatar size="small" icon={<UserOutlined />} style={{ backgroundColor: "#003087" }} />
              <div className="text-sm">
                <div className="font-medium text-gray-700 leading-tight">{user.name}</div>
                <div className="text-xs text-gray-400 flex items-center gap-1">
                  {user.email}
                  <Tag color={user.role === "admin" ? "red" : user.role === "editor" ? "blue" : "default"} className="ml-1" style={{ fontSize: 10, padding: "0 4px", lineHeight: "16px" }}>
                    {user.role === "admin" ? "Admin" : user.role === "editor" ? "Biên tập" : "Xem"}
                  </Tag>
                </div>
              </div>
            </div>
          </Dropdown>
        </Header>
        <Content style={{ padding: 24, background: "#f5f6fa" }}>
          {children}
        </Content>
      </Layout>
    </Layout>
  );
}

export default function AdminLayout({ children }: { children: React.ReactNode }) {
  return (
    <SessionProvider>
      <AdminLayoutInner>{children}</AdminLayoutInner>
    </SessionProvider>
  );
}

