using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using KtsVinhLong.Data;
using KtsVinhLong.Models;
using System.Linq;
using System.Threading.Tasks;

namespace KtsVinhLong.Controllers
{
    // [Authorize] - Đã bỏ theo yêu cầu của bạn
    public class AdminController : Controller
    {
        private readonly KtsDbContext _context;

        public AdminController(KtsDbContext context)
        {
            _context = context;
        }

        public async Task<IActionResult> Index()
        {
            var tongHeThong = await _context.HeThongSos.CountAsync();
            var tongNhiemVu = await _context.NhiemVus.CountAsync();
            var nhiemVuHoanThanh = await _context.NhiemVus.CountAsync(n => n.TrangThai == "hoan-thanh");
            var nhiemVuTreHan = await _context.NhiemVus.CountAsync(n => n.TrangThai == "tre-han");

            ViewBag.TongHeThong = tongHeThong;
            ViewBag.TongNhiemVu = tongNhiemVu;
            ViewBag.NhiemVuHoanThanh = nhiemVuHoanThanh;
            ViewBag.NhiemVuTreHan = nhiemVuTreHan;

            ViewBag.PhanTramHoanThanh = tongNhiemVu > 0 ? (nhiemVuHoanThanh * 100 / tongNhiemVu) : 0;

            return View();
        }

        public async Task<IActionResult> HeThong()
        {
            var systems = await _context.HeThongSos.Include(h => h.DonVi).ToListAsync();
            return View(systems);
        }

        public async Task<IActionResult> NhiemVu()
        {
            var tasks = await _context.NhiemVus.Include(n => n.DonViChuTri).ToListAsync();
            return View(tasks);
        }
    }
}

@{
    ViewData["Title"] = "Dashboard Tổng quan";
    Layout = "_AdminLayout";
}

<div class="grid grid-cols-4 gap-6 mb-8">
    <div class="bg-white p-6 rounded-xl shadow-sm border-l-4 border-blue-500">
        <div class="text-sm text-gray-500 font-medium mb-1">Tổng Hệ thống Số</div>
        <div class="text-3xl font-bold text-gray-800">@ViewBag.TongHeThong</div>
    </div>

    <div class="bg-white p-6 rounded-xl shadow-sm border-l-4 border-indigo-500">
        <div class="text-sm text-gray-500 font-medium mb-1">Tổng Nhiệm vụ</div>
        <div class="text-3xl font-bold text-gray-800">@ViewBag.TongNhiemVu</div>
    </div>

    <div class="bg-white p-6 rounded-xl shadow-sm border-l-4 border-green-500">
        <div class="text-sm text-gray-500 font-medium mb-1">Hoàn thành</div>
        <div class="text-3xl font-bold text-green-600">@ViewBag.NhiemVuHoanThanh <span class="text-sm text-gray-400">(@ViewBag.PhanTramHoanThanh%)</span></div>
    </div>

    <div class="bg-white p-6 rounded-xl shadow-sm border-l-4 border-red-500">
        <div class="text-sm text-gray-500 font-medium mb-1">Trễ hạn</div>
        <div class="text-3xl font-bold text-red-600">@ViewBag.NhiemVuTreHan</div>
    </div>
</div>

<div class="grid grid-cols-2 gap-6">
    <div class="bg-white p-6 rounded-xl shadow-sm">
        <h3 class="font-bold text-gray-800 mb-4">Tiến độ tổng thể</h3>
        <div class="w-full bg-gray-200 rounded-full h-4 mb-4">
            <div class="bg-blue-600 h-4 rounded-full" style="width: @ViewBag.PhanTramHoanThanh%"></div>
        </div>
        <div class="flex justify-between text-sm text-gray-500">
            <span>Đã hoàn thành @ViewBag.PhanTramHoanThanh%</span>
            <span>100% Mục tiêu</span>
        </div>
    </div>

    <div class="bg-white p-6 rounded-xl shadow-sm">
        <h3 class="font-bold text-gray-800 mb-4">Phân bổ Nhiệm vụ</h3>
        <canvas id="myChart" height="100"></canvas>
    </div>
</div>

@section Scripts {
    <script>
        const ctx = document.getElementById('myChart');
        new Chart(ctx, {
            type: 'doughnut',
            data: {
                labels: ['Hoàn thành', 'Chưa bắt đầu / Đang làm', 'Trễ hạn'],
                datasets: [{
                    data: [
                        @ViewBag.NhiemVuHoanThanh, 
                        @ViewBag.TongNhiemVu - @ViewBag.NhiemVuHoanThanh - @ViewBag.NhiemVuTreHan, 
                        @ViewBag.NhiemVuTreHan
                    ],
                    backgroundColor: ['#22c55e', '#3b82f6', '#ef4444'],
                    borderWidth: 0
                }]
            },
            options: {
                cutout: '70%',
                plugins: {
                    legend: { position: 'bottom' }
                }
            }
        });
    </script>
}

