"use client";
import { useState, useEffect } from "react";
import Link from "next/link";
import { Tag, Modal, Button, Spin, Tooltip } from "antd";
import {
  ApartmentOutlined,
  DatabaseOutlined,
  GlobalOutlined,
  BankOutlined,
  SafetyCertificateOutlined,
  ThunderboltOutlined,
  RightOutlined,
  FileProtectOutlined,
  CloudServerOutlined,
  MobileOutlined,
  NodeIndexOutlined,
  LockOutlined,
  DesktopOutlined,
  FundProjectionScreenOutlined,
  RobotOutlined,
  DeploymentUnitOutlined,
  AuditOutlined,
  ShopOutlined,
  MedicineBoxOutlined,
  EnvironmentOutlined,
  EyeOutlined,
  CompassOutlined,
  AppstoreOutlined,
  CheckCircleOutlined,
  ArrowRightOutlined,
  BarChartOutlined,
} from "@ant-design/icons";
import { HeThongSoData, NhiemVuData } from "@/types";
import { TRANG_THAI_CONFIG } from "@/lib/utils";

interface FrameworkBlock {
  id: string;
  title: string;
  description: string;
  icon: React.ReactNode;
  lop: number;
  category: string;
  itemsMatch: (ht: HeThongSoData) => boolean;
  tasksMatch: (nv: NhiemVuData) => boolean;
  color: string;
  bgColor: string;
  borderColor: string;
}

export default function SoDoKhungKTSPage() {
